$ErrorActionPreference = "Stop"

$b64 = ""

$bytes = [Convert]::FromBase64String($b64)
Write-Host "Decoded byte count: $($bytes.Length)"

$repoRoot = (Get-Location).Path
$relativePath = "ecosystem\applications\arcturus\src\control_plane\scenarios\scenario_controller.py"
$fullPath = Join-Path -Path $repoRoot -ChildPath $relativePath

Write-Host "Repo root resolved as: $repoRoot"
Write-Host "Writing to: $fullPath"

if (Test-Path $fullPath) {
    Write-Host "WARNING: file already exists at that path. Aborting so nothing is overwritten." -ForegroundColor Yellow
    exit 1
}

[IO.File]::WriteAllBytes($fullPath, $bytes)

Get-Item $fullPath | Select-Object FullName, Length